INSERT OR IGNORE INTO Page (id, title, slug, content, seoDescription, featuredImage, status, publishedAt, updatedAt) VALUES (12963, 'Bẫy tự tin &#8211; Làm sao vượt qua và tìm thấy sự tự tin thật sự', 'bay-tu-tin', '
<p><strong>Dường như không thể thành công nếu không có mức độ tự tin nhất định. Tuy nhiên, làm sao bạn có thể tự tin khi chưa đạt được mức độ thành công nào đó?</strong></p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>Đó là một tình huống con gà và quả trứng. Khi bạn thấy ai đó thành công và tự tin, điều gì đến trước tiên? Sự tự tin hay thành công?</p>
</blockquote>



<h2 class="wp-block-heading">Thành công ở một lĩnh vực, không hẳn đã là người tự tin&#8230;</h2>



<p>Tôi nhớ từng biết một người dường như có tất cả. Người đó thông minh, giàu có, hấp dẫn, đẹp trai và có rất nhiều bạn bè.</p>



<p>Tuy nhiên, họ dường như cũng thu hút một chuỗi các mối quan hệ độc hại. Thất bại nối tiếp thất bại. Lần nào cũng vậy, đối tác của họ sẽ đi khắp nơi, coi họ như tấm thảm chùi chân.</p>



<p>Nó làm tôi bối rối, tôi tự hỏi, nó là số mệnh gì đó chăng? Một ngày nọ, chúng tôi thảo luận về cuộc tình thất bại mới nhất, và tôi nói: &#8220;Tại sao anh lại phải chịu đựng điều đó? Anh hoàn hảo với nhiều thứ. Anh không cần phải chịu đựng điều đó.&#8221;</p>



<p>Khi cuộc trò chuyện diễn ra, tôi nhận ra người đó cảm thấy không xứng đáng với tình yêu và một mối quan hệ tốt đẹp. Người đó thiếu sự tự tin mà tôi cho là người đó có và đã đánh giá sai tình hình. Người đó là những người cảm thấy may mắn khi có người đồng hành cùng mình.</p>



<p>Tôi đã trải qua những thất bại đáng kể trong học tập, công việc và cuộc sống. Tôi cũng từng có những mối tình thất bại.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>Tôi nhớ mình đã nghĩ: &#8220;Chết tiệt. Nếu ai đó có tất cả mà vẫn không cảm thấy tự tin thì mình còn cơ hội gì nữa? Mình hỏng rồi.&#8221;</p>
</blockquote>



<h2 class="wp-block-heading">Chấp nhận sự thất bại</h2>



<p>Trớ trêu thay, một khi tôi cảm thấy mình không có cơ hội đạt được thành công đáng kể, tôi bắt đầu tìm thấy niềm vui gần như ngang ngược khi cố gắng đạt được mặt trăng và thất bại.</p>



<p>Cuộc đối thoại nội tâm của tôi không phải là <strong>&#8220;Tôi có thể làm bất cứ điều gì!&#8221;</strong> Nó giống như, <strong>&#8220;Ơ, ai quan tâm chứ. Cũng nên thử xem. Điều tồi tệ nhất có thể xảy ra là gì?&#8221;</strong></p>



<p>Nhưng, một điều kỳ lạ đã xảy ra. Tôi <strong>thường xuyên thất bại, nhưng tôi cũng bắt đầu thành công</strong>. Không ồ ạt nhưng vừa <strong>đủ để tiếp tục tiến về phía trước và đạt được những cột mốc quan trọng</strong> trong cuộc đời.</p>



<p>Đủ để cưới một người phụ nữ vượt xa trí tuệ của tôi. Đủ để theo đuổi bằng thạc sĩ sau nhiều năm học tập tầm thường. Đủ để có được một công việc tại công ty mơ ước của tôi.</p>



<p>Cho đến hôm nay, tôi không còn cảm thấy sự &#8220;tự tin cổ điển&#8221; nữa. Tôi biết điều gì là đúng về bản thân mình, nhưng <strong>tôi cũng chấp nhận những gì tôi sẽ không bao giờ trở thành</strong>.</p>



<p>Tuy nhiên, tôi không còn quan tâm đến những khuyết điểm đó nữa. Tôi đã <strong><mark style="background-color:rgba(0, 0, 0, 0)" class="has-inline-color has-vivid-cyan-blue-color">chịu đựng rất nhiều thất bại, nhưng tôi đã vượt qua chúng và sống sót</mark></strong>.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>&#8220;Bạn có được sức mạnh, lòng can đảm và sự tự tin nhờ mọi trải nghiệm mà bạn thực sự dừng lại để nhìn thẳng vào nỗi sợ hãi. Bạn có thể tự nhủ: &#8216;<strong>Tôi đã sống qua nỗi kinh hoàng này. Tôi có thể đương đầu với điều tiếp theo xảy đến</strong>.&#8217; &#8221; &#8211; Eleanor Roosevelt</p>
</blockquote>



<p>Tôi không ngừng phấn đấu và nỗ lực. Đó có phải là sự tự tin? Có lẽ.</p>



<h2 class="wp-block-heading">Công nhận sự tự tin thực sự</h2>



<p>Tuổi tác đi kèm với một chút khôn ngoan. Bạn bắt đầu nhìn thấu những chiếc mặt nạ mà mọi người đều đeo. Bạn nhìn xa hơn những lớp nhận dạng mong đợi mà mọi người đã xây dựng.</p>



<p>Bạn nhận ra sự tự tin thực sự &#8211; <strong>những người trầm lặng, chăm chỉ, rộng lượng và khiêm tốn đến đáng ngạc nhiên.</strong></p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>Bạn cũng biết khi nào ai đó đang biểu diễn. Bạn cảm thấy mệt mỏi với việc liên tục khoe khoang, thống trị mọi cuộc trò chuyện và lợi dụng mọi người trong phòng bằng những câu chuyện về cách họ đã cứu thế giới (một lần nữa).</p>
</blockquote>



<p>Bạn nên biết rằng một số người dường như “có tất cả” lại thiếu tự tin. Mặc dù mồm to và những câu chuyện thậm chí còn ồn ào hơn, họ không tin vào chính mình.</p>



<p>Những người được bao quanh bởi sự hào nhoáng của thành công hiếm khi thành công như họ tưởng tượng.</p>



<ul class="wp-block-list">
<li>Người mặc bộ trang phục thiết kế mới nhất đang ngồi trong chiếc ô tô sang trọng mới toanh của họ ở cột đèn giao thông bên phải bạn? Họ chìm trong nợ nần, ghét công việc của mình và phải hôn chân ông chủ để được trả lương.</li>



<li>Người mặc áo phông và quần jean, lái chiếc xe cũ nát của họ ở bên trái bạn? Họ nghỉ hưu ở tuổi 40, có tài sản hàng tỷ đồng và không mắc nợ.</li>
</ul>



<p>Nghĩ rằng tôi có đầy đủ nó với những quan sát này?</p>



<ul class="wp-block-list">
<li>Warren Buffett có tài sản ròng trị giá hơn 80 tỷ USD nhưng vẫn sống trong ngôi nhà khiêm tốn mà ông mua từ những năm 1950. <a href="https://cafef.vn/ty-phu-warren-buffett-me-cola-va-mcdonalds-van-minh-man-tinh-tuong-o-tuoi-91-bi-quyet-song-tho-an-vui-goi-gon-trong-3-thoi-quen-don-gian-20211001171751202.chn" target="_blank" rel="noreferrer noopener">Ông ấy dừng lại ở McDonald&#8217;s để chi khoảng 3 đô la cho bữa sáng</a> trên đường đến văn phòng.</li>



<li>Jeff Bezos có tài sản ròng trị giá hơn 100 tỷ USD (ngay cả sau khi ly hôn). <a href="https://vtc.vn/ty-phu-the-gioi-lai-xe-gi-ar690596.html#:~:text=Jeff%20Bezos%20%2D%20Honda%20Accord%201999&amp;text=%C3%94ng%20t%E1%BB%ABng%20l%C3%A1i%20c%C3%A1c%20g%C3%B3i,chi%E1%BA%BFc%20xe%20ho%C3%A0n%20to%C3%A0n%20t%E1%BB%91t%22." target="_blank" rel="noreferrer noopener">Ông vẫn lái chiếc Honda Accord đi làm hàng ngày</a> sau khi trở thành tỷ phú vào năm 1999.</li>



<li>Mặt khác, <a href="https://vi.wikipedia.org/wiki/Bernard_Ebbers" target="_blank" rel="noreferrer noopener">Bernard Ebbers</a> đã tính toán với khoản nợ hơn 1 tỷ USD để mua du thuyền, nhà máy đóng tàu, trang trại, v.v. Anh ta có tất cả vẻ bề ngoài của sự giàu có và thành công, nhưng tất cả chỉ là bề ngoài. Cuối cùng, anh ta bị kết án 25 năm tù vì dàn dựng một vụ gian lận kế toán trị giá 11 tỷ USD.</li>
</ul>



<p>Sự tự tin không đến từ sự xác nhận bên ngoài hoặc những dấu hiệu thành công bề ngoài điển hình. Đó không phải là về ngoại hình của bạn. Số tiền vô tận và những danh hiệu xa hoa sẽ không mang lại cho bạn sự tự tin.</p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>“Tự tin không phải là ‘Họ sẽ thích tôi.’ Thay vào đó, sự tự tin là &#8216;Tôi sẽ ổn nếu họ không làm vậy.''&#8221; &#8211; Christina Grimmie</p>
</blockquote>



<p>Trớ trêu thay, việc trở nên thành công hơn trong cuộc sống và sự nghiệp có thể khiến bạn bất an hơn (Hawley, Katherine. “I — What Is Impostor Syndrome? (Hội chứng kẻ mạo danh)&#8221; Aristotelian Society Supplementary Volume 93.1 (2019)). <strong>Bạn cảm thấy mình như một kẻ lừa đảo và mạo danh. Mọi người sẽ nhận ra bạn không tài năng đến thế. Bạn sẽ mất tất cả.</strong></p>



<h2 class="wp-block-heading">Nhưng điều gì tạo nên sự tự tin?</h2>



<p>Sự tự tin không đi kèm với thành tích. Nó đi kèm với sự phấn đấu và tin tưởng vào những gì bạn có thể làm.</p>



<p>Hãy tự tin rằng bạn sẽ <strong>học được cách làm điều gì đó</strong>.</p>



<p>Hãy tự tin rằng bạn sẽ <strong>làm việc chăm chỉ</strong>.</p>



<p>Hãy tự tin vào <strong>lòng can đảm và quyết tâm của bạn</strong>.</p>



<p>Hay khám phá những sự thật cốt lõi của bạn trước đây. Hãy đào sâu và khẳng định những điều đúng đắn ở bạn và không bao giờ có thể bị lấy đi &#8211; hãy biến điều đó thành nền tảng cho sự tự tin và xua tan hội chứng kẻ mạo danh của bạn.</p>



<p>Sự tự tin và bình tĩnh cũng đi kèm với việc <strong><mark style="background-color:rgba(0, 0, 0, 0)" class="has-inline-color has-vivid-cyan-blue-color">chấp nhận những gì bạn không có</mark></strong>, sẽ không bao giờ có và không bao giờ phải có. Hãy gạt những điều vô nghĩa đó sang một bên, ra khỏi tâm trí và cuộc sống của bạn.</p>



<p><em>Nếu tôi không quan tâm đến việc xuất sắc ở một việc gì đó, tôi không thể thiếu tự tin để làm tốt việc đó. Nó thậm chí còn không được ghi nhận trên thang đo tài năng, khả năng và kỹ năng của tôi.</em></p>



<p><strong><mark style="background-color:rgba(0, 0, 0, 0)" class="has-inline-color has-vivid-cyan-blue-color">Không, tôi sẽ không bao giờ trở thành một cầu thủ bóng đá giỏi. Tôi cũng không quan tâm đến điều đó. Nó không có ý nghĩa gì trong cuộc sống của tôi. Tôi không bị tổn thương hay thiếu tự tin vào kỹ năng chơi bóng đá của mình vì tôi không quan tâm đến nó.</mark></strong></p>



<p>Mark Manson nói về việc trở nên thoải mái với thất bại, sự từ chối và nỗi đau. Những người tự tin nhất không tràn đầy tự tin vì họ tin rằng họ sẽ luôn thành công và không bao giờ thất bại. Sự tự tin của họ bắt nguồn từ việc chấp nhận rằng thất bại là một lựa chọn và biết rằng họ có thể vượt qua nó và quay trở lại.</p>



<p><strong>Những người tự tin không phải lúc nào cũng nói &#8220;Tôi sẽ thắng&#8221;.</strong></p>



<p><strong><mark style="background-color:rgba(0, 0, 0, 0)" class="has-inline-color has-vivid-red-color">Người tự tin nói: “Tôi sẽ cố gắng hết sức và dù có chuyện gì xảy ra thì cũng sẽ ổn thôi”.</mark></strong></p>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>&#8220;Tôi nghĩ sức mạnh đó chính là nguyên tắc. Nguyên tắc tiến về phía trước, như thể bạn có đủ tự tin để tiến về phía trước, cuối cùng sẽ mang lại cho bạn sự tự tin khi nhìn lại và xem những gì mình đã làm.&#8221; —Robert Downey, Jr.</p>
</blockquote>



<p>Sẽ thật ngu ngốc &#8211; và gây tổn hại đến sự tự tin của bạn &#8211; nếu cho rằng và mong đợi thành công 100%. Thất bại là điều không thể tránh khỏi. Nếu bạn đặt niềm tin vào lòng dũng cảm và những lời tuyên bố về thành công vĩnh cửu, bạn sẽ bị đánh thức một cách thô bạo.</p>



<h2 class="wp-block-heading">Phá vỡ chu kỳ bằng cách sở hữu những gì bạn có thể kiểm soát</h2>



<p>Như Fred Kofman đã chỉ ra trong cuốn “Kinh doanh có ý thức: Cách xây dựng giá trị thông qua các giá trị”, chúng ta tập trung quá nhiều vào kết quả. Chúng ta mất niềm tin vào bản thân, mất tinh thần và thậm chí trở nên tức giận khi không giành chiến thắng, thành công hoặc thay đổi suy nghĩ của ai đó.</p>



<p>Tuy nhiên, bạn không thể kiểm soát được kết quả. Bạn không nên ép buộc người khác làm theo mệnh lệnh của mình (hơn nữa, điều đó trái đạo đức). Bạn sẽ không kiểm soát được môi trường theo ý thích của mình. Tuy nhiên, bạn có thể kiểm soát các giá trị, hành động và nỗ lực của mình.</p>



<p>Tập trung vào những gì bạn có thể làm và để sự tự tin đến một cách tự nhiên từ việc tin vào hành động của bạn.</p>



<ul class="wp-block-list">
<li>Làm nhiều hơn và nói ít hơn.</li>



<li>Tìm hiểu nhiều hơn và khoe khoang ít hơn.</li>



<li>Thất bại nhiều hơn và mong đợi ít hơn.</li>



<li>Cho nhiều hơn và nhận ít hơn.</li>



<li>Tiết kiệm nhiều hơn và chi tiêu ít hơn.</li>
</ul>



<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">
<p>Cách đáng ngạc nhiên nhất để phá vỡ vòng luẩn quẩn “sự tự tin đòi hỏi thành công” là trở nên thoải mái với thất bại và bị từ chối. Hãy đặt niềm tin vào sự thật cốt lõi, lòng dũng cảm và sự quyết tâm của bạn.</p>



<p>Đừng tập trung vào thành công, thành tích hoặc bất kỳ dấu hiệu thành công bên ngoài nào khác. Một khi bạn thực hiện sự thay đổi đó, không gì có thể lấy đi sự tự tin của bạn.</p>
</blockquote>
', 'Dường như không thể thành công nếu không có mức độ tự tin nhất định. Tuy nhiên, làm sao bạn có thể tự tin khi chưa đạt được mức độ thành công nào đó? Đó là một tình huống con gà và quả trứng. Khi bạn thấy ai đó thành công và tự tin, điều [&hellip;]', 12964, 'post', '2024-09-06 21:39:47', '2024-09-06 21:39:49');
